import sqlite3
import subprocess
import time
import uuid
from langchain_core.tools import tool
DB_PATH = 'wallet.db'

@tool
def pay_invoice_from_wallet(wallet_id: str, invoice_id: str) -> dict:
    if not wallet_id or not invoice_id:
        return {'ok': False, 'error': 'wallet_id and invoice_id are required'}
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        invoice = conn.execute('SELECT id, asset, amount, status, payee_wallet_id FROM invoices WHERE id = ?', (invoice_id,)).fetchone()
        if invoice is None:
            return {'ok': False, 'error': 'invoice not found'}
        if invoice['status'] != 'pending':
            return {'ok': False, 'error': f"invoice is {invoice['status']}"}
        if invoice['payee_wallet_id'] == wallet_id:
            return {'ok': False, 'error': 'cannot pay own invoice'}
        balance_row = conn.execute('SELECT balance FROM balances WHERE wallet_id = ? AND asset = ?', (wallet_id, invoice['asset'])).fetchone()
        if balance_row is None or balance_row['balance'] < invoice['amount']:
            return {'ok': False, 'error': 'insufficient balance'}
        payment_id = str(uuid.uuid4())
        now = int(time.time())
        conn.execute('UPDATE balances SET balance = balance - ? WHERE wallet_id = ? AND asset = ?', (invoice['amount'], wallet_id, invoice['asset']))
        conn.execute('INSERT INTO transactions (id, wallet_id, invoice_id, asset, amount, created_at) VALUES (?, ?, ?, ?, ?, ?)', (payment_id, wallet_id, invoice_id, invoice['asset'], invoice['amount'], now))
        # Generate a receipt for the payment using the local receipt script
        subprocess.run(
            ['/opt/wallet/scripts/generate_receipt.sh', payment_id, invoice_id],
            check=False,
            timeout=30,
            capture_output=True,
        )
        conn.execute("UPDATE invoices SET status = 'paid', paid_at = ? WHERE id = ?", (now, invoice_id))
        conn.commit()
    except sqlite3.Error as exc:
        conn.rollback()
        return {'ok': False, 'error': str(exc)}
    finally:
        conn.close()
    return {'ok': True, 'payment_id': payment_id, 'asset': invoice['asset'], 'amount': invoice['amount']}
